  opacity {transition.duration-pop} {ease.out},
  translate {transition.duration-pop} {ease.out},
  display {transition.duration-pop} allow-discrete;

@starting-style {
  opacity: 0;
  translate: 0 -4px;
}

&:hover {
  background-color: color-mix(in oklab, {color.ink} 5%, transparent);
}

&[data-state="removed"] {
  display: none;
  opacity: 0;
  translate: -8px 0;
  transition-duration: {transition.duration-pop-exit};
}

@media (prefers-reduced-motion: reduce) {
  transition-property: background-color, opacity, display;

  @starting-style {
    translate: none;
  }
}

